use std::env;

use axum::{
    body::{to_bytes, Body},
    extract::Request,
    http::{header, HeaderMap, StatusCode},
    response::{IntoResponse, Response},
    routing::{any, get, post},
    Router,
};
use fullstack_agent_046::{calculate, RequestInput};
use serde::Serialize;
use serde_json::json;
use tower_http::services::{ServeDir, ServeFile};

const MAX_BODY_BYTES: usize = 16_384;
const BROWSER_MODULE: &str = r#"const asI64=(v,n)=>{if(typeof v==='bigint')return v;if(!Number.isSafeInteger(v))throw new TypeError(`${n} must be a safe whole number`);return BigInt(v)};export async function loadParley(){const r=await fetch(new URL('/fullstack_agent_046.wasm',import.meta.url));const m=(await WebAssembly.instantiateStreaming(r)).instance.exports;return {estuary_assay_rating:(a0,a1,a2,a3,a4)=>m.parley_browser_score(asI64(a0,'a0'),asI64(a1,'a1'),asI64(a2,'a2'),asI64(a3,'a3'),a4?1:0)}}"#;

fn json_response(value: impl Serialize, status: u16, headers: &[(&str, &str)]) -> Response {
    if headers.iter().any(|(name, _)| matches!(name.to_ascii_lowercase().as_str(), "content-length" | "content-type" | "connection" | "transfer-encoding" | "x-content-type-options")) {
        return error("invalid_response_headers", 500, "server-owned response header");
    }
    let mut response = (StatusCode::from_u16(status).unwrap(), serde_json::to_vec(&value).unwrap()).into_response();
    response.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("application/json"));
    for (name, value) in headers {
        response.headers_mut().insert(header::HeaderName::from_bytes(name.as_bytes()).unwrap(), header::HeaderValue::from_str(value).unwrap());
    }
    response
}

fn error(code: &str, status: u16, detail: &str) -> Response {
    let mut response = (StatusCode::from_u16(status).unwrap(), serde_json::to_vec(&json!({"error": code, "detail": detail})).unwrap()).into_response();
    response.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("application/json"));
    response
}

fn zero(v: &RequestInput, state: &str) -> serde_json::Value {
    json!({"assay_ref":v.assay_ref,"sample_tally":0,"assay_effort":0,"bench_allowance":0,"examined_effort":0,"pending_assay":0,"assay_cycles":0,"assay_rating":0,"assay_phase":state})
}

fn decide(v: RequestInput, headers: &HeaderMap) -> Response {
    if headers.get("authorization").and_then(|value| value.to_str().ok()).unwrap_or("") != "Sample sample-046" {
        return json_response(zero(&v, "authorization_required"), 401, &[("www-authenticate", "Sample realm=estuary")]);
    }
    if [v.inlet_vials, v.outlet_vials, v.reagent_cartridges, v.assay_benches].iter().any(|value| *value < 0) {
        return json_response(zero(&v, "invalid"), 422, &[("x-validation", "nonnegative")]);
    }
    if v.assay_benches == 0 && v.inlet_vials + v.outlet_vials > 0 {
        return json_response(zero(&v, "invalid"), 422, &[("x-validation", "assay_benches")]);
    }
    if v.repeated_submission {
        return json_response(zero(&v, "duplicate"), 409, &[("x-conflict", "repeated_submission")]);
    }
    let output = calculate(&v);
    let phase = output.assay_phase.clone();
    let location = format!("/api/v10/estuary-assays/{}", v.assay_ref);
    json_response(output, 202, &[("location", &location), ("retry-after", "5"), ("x-assay-phase", &phase)])
}

async fn status() -> Response { json_response(json!({"service":"Estuary Assay Dispatch","ready":true}), 200, &[]) }

async fn endpoint(request: Request) -> Response {
    let headers = request.headers().clone();
    let media = headers.get(header::CONTENT_TYPE).and_then(|value| value.to_str().ok()).unwrap_or("").split(';').next().unwrap_or("").trim().to_ascii_lowercase();
    if media != "application/json" && !media.ends_with("+json") { return error("json_content_type_required", 415, "expected application/json"); }
    if let Some(length) = headers.get(header::CONTENT_LENGTH) {
        let declared = length.to_str().ok().and_then(|value| value.parse::<usize>().ok());
        if declared.is_none_or(|value| value > MAX_BODY_BYTES) { return error("body_too_large", 413, "request body exceeds 16384 bytes"); }
    }
    let body = match to_bytes(request.into_body(), MAX_BODY_BYTES).await { Ok(body) => body, Err(_) => return error("body_too_large", 413, "request body exceeds 16384 bytes") };
    match serde_json::from_slice::<RequestInput>(&body) { Ok(value) => decide(value, &headers), Err(reason) => error("invalid_json", 400, &reason.to_string()) }
}

async fn missing(request: Request<Body>) -> Response { error("not_found", 404, &format!("no API route {}", request.uri().path())) }
async fn browser() -> Response { let mut response = BROWSER_MODULE.into_response(); response.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("text/javascript; charset=utf-8")); response }

#[tokio::main]
async fn main() {
    let wasm = env::var_os("FULLSTACK_046_WASM").map(std::path::PathBuf::from).unwrap();
    let app = Router::new().route("/status/estuary-assay-ready", get(status)).route("/api/v10/estuary-assays", post(endpoint)).route("/api/{*rest}", any(missing)).route("/parley.js", get(browser)).route_service("/fullstack_agent_046.wasm", ServeFile::new(wasm)).fallback_service(ServeDir::new("public").append_index_html_on_directories(true));
    let port = env::var("PARLEY_WEB_PORT").unwrap().parse::<u16>().unwrap();
    let listener = tokio::net::TcpListener::bind(("127.0.0.1", port)).await.unwrap();
    axum::serve(listener, app).await.unwrap();
}
